{
  "a_sentences": [
    {
      "a_text": "Le Tribunal fédéral ne peut revenir sur ses arrêts que si l'un des motifs de révision exhaustivement énumérés aux art. 121 ss LTF est réalisé.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "La personne demandant la révision d'un arrêt du Tribunal fédéral doit indiquer un motif prévu par la loi et démontrer en quoi l'arrêt attaqué souffre d'un vice révisoire.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "Dans le cadre d'un recours en matière de droit public, la personne requérant la révision doit prouver cumulativement plusieurs éléments, notamment que la nouvelle preuve existait déjà au moment de l'arrêt attaqué, qu'elle a été découverte après coup et qu'elle n'a pas pu être produite malgré une diligence raisonnable.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "Une appréciation erronée des preuves ou une mauvaise application du droit ne constitue pas un motif de révision.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "Le Tribunal fédéral rejette le recours en révision dans toutes ses conclusions, dès lors qu'il n'existe aucun motif de révision valable.",
      "b_propositions": ["P5"]
    }
  ]
}
